using System.Text.Json;
using System.Text.RegularExpressions;
using Humcp.Schema;

namespace Humcp.Core;

/// <summary>
/// The form a server is added or edited with, generated by the same <see cref="FormBuilder"/> as
/// every tool's (ROADMAP §10, Phase 6). humcp's own settings get the whole accessibility contract —
/// names, labels, help text, required state, access keys, the error summary — for the price of a
/// schema, and every defect a screen reader ever found in a generated form is already fixed here.
/// </summary>
/// <remarks>
/// <para>
/// <b>The form is filled in, not defaulted.</b> A tool form's omission rule says an untouched
/// default is not sent (§5), which makes "the user cleared the working directory" and "the user did
/// not touch it" the same answer. That is right for a server, which has its own default to fall
/// back on, and wrong here, where the value on screen <em>is</em> the configuration. So the schema
/// states no defaults, <see cref="Fill"/> puts the current values in the boxes, and
/// <see cref="Read"/> reads the boxes rather than the argument object.
/// </para>
/// <para>
/// <b>Here, client-side validation is the authority.</b> "Never block on client validation" exists
/// because the server knows better than the client what it accepts (§5). This schema is humcp's own,
/// so there is nobody to defer to, and an entry that would not start is refused with a reason.
/// </para>
/// </remarks>
public static class ServerForm
{
    public const string NameField = "name";
    public const string CommandField = "command";
    public const string AddressField = "address";
    public const string ArgumentsField = "arguments";
    public const string DirectoryField = "directory";
    public const string EnvironmentField = "environment";
    public const string EnabledField = "enabled";

    /// <summary>The one field of the import form.</summary>
    public const string ImportField = "configuration";

    /// <summary>A variable name, an equals sign, and anything at all after it.</summary>
    private static readonly Regex Variable = new("^([A-Za-z_][A-Za-z0-9_]*)=(.*)$", RegexOptions.Singleline);

    /// <summary>
    /// The add-or-edit form. Order is the order a person thinks in: what to call it, what to run,
    /// what to run it with.
    /// </summary>
    public static FormModel Model { get; } = FormBuilder.Build(Parse("""
        {
          "type": "object",
          "properties": {
            "name": {
              "type": "string", "title": "Name", "minLength": 1, "maxLength": 200,
              "description": "What the tree calls this server."
            },
            "command": {
              "type": "string", "title": "Command",
              "description": "The program that starts the server, such as npx, uvx or the full path to an executable, or empty for a server reached by address."
            },
            "address": {
              "type": "string", "title": "Address",
              "description": "Instead of a command, the web address of a server reached over HTTP, starting with https://."
            },
            "arguments": {
              "type": "string", "title": "Arguments",
              "description": "Everything after the command on one line, with double quotes around any argument that has a space in it."
            },
            "directory": {
              "type": "string", "title": "Working directory",
              "description": "The folder the server starts in, or empty for humcp's own."
            },
            "environment": {
              "type": "array", "title": "Environment variables",
              "description": "One NAME=value each, usually an API key, kept in plain text in servers.json as every MCP client keeps them.",
              "items": { "type": "string", "pattern": "^[A-Za-z_][A-Za-z0-9_]*=" }
            },
            "enabled": {
              "type": "boolean", "title": "Start this server",
              "description": "Untick to keep the server in the list without starting it."
            }
          },
          "required": ["name"]
        }
        """));

    /// <summary>One box to paste a configuration into.</summary>
    public static FormModel ImportModel { get; } = FormBuilder.Build(Parse("""
        {
          "type": "object",
          "properties": {
            "configuration": {
              "type": "string", "title": "Configuration", "minLength": 1, "maxLength": 200000,
              "description": "Paste an mcpServers block, a whole configuration file from another MCP client, or one server's entry."
            }
          },
          "required": ["configuration"]
        }
        """));

    /// <summary>
    /// Puts a server's current configuration in the boxes, or a new server's starting values —
    /// which is only "start it", ticked, because a server just added is a server someone wants.
    /// </summary>
    public static void Fill(FormState state, ServerDescriptor? current)
    {
        ArgumentNullException.ThrowIfNull(state);

        SetText(state, NameField, current?.DisplayName);
        SetText(state, CommandField, current?.Command);
        SetText(state, AddressField, current?.Url);
        SetText(state, ArgumentsField, current is null ? null : ServerDescriptor.JoinArguments(current.Arguments));
        SetText(state, DirectoryField, current?.WorkingDirectory);

        if (state.Find(EnvironmentField) is ListFieldState environment && current is not null)
        {
            foreach (var (name, value) in current.Environment)
            {
                if (environment.Draft is not TextFieldState draft) break;
                draft.Text = $"{name}={value}";
                environment.AddDraft();
            }
        }

        if (state.Find(EnabledField) is BooleanFieldState enabled) enabled.Value = current?.Enabled ?? true;
    }

    /// <summary>
    /// What is in the boxes, as a configuration entry — or a sentence saying why it is not one yet.
    /// </summary>
    /// <param name="id">The key to file it under: the existing one when editing, a new one when adding.</param>
    /// <param name="current">The entry being edited, whose URL and other members are carried over.</param>
    public static ServerDescriptor? Read(FormState state, string id, ServerDescriptor? current, out string? problem)
    {
        ArgumentNullException.ThrowIfNull(state);

        problem = null;

        var name = Text(state, NameField);
        var command = Text(state, CommandField);

        if (name.Length == 0)
        {
            problem = "Name: the server needs a name.";
            return null;
        }

        var address = Text(state, AddressField);

        if (command.Length == 0 && address.Length == 0)
        {
            problem = "Command: the server needs a command to start it, or an address to reach it at.";
            return null;
        }

        if (command.Length > 0 && address.Length > 0)
        {
            problem = "Address: a server is started by a command or reached at an address, not both. Empty one of them.";
            return null;
        }

        if (address.Length > 0
            && (!Uri.TryCreate(address, UriKind.Absolute, out var endpoint) || endpoint.Scheme is not ("http" or "https")))
        {
            problem = "Address: this has to be a web address starting with https:// or http://.";
            return null;
        }

        var environment = new Dictionary<string, string>(StringComparer.Ordinal);

        if (state.Find(EnvironmentField) is ListFieldState list)
        {
            foreach (var entry in list.Items.OfType<TextFieldState>())
            {
                var match = Variable.Match(entry.Text.Trim());

                if (!match.Success)
                {
                    problem = $"Environment variables: \"{TextSanitizer.Clean(entry.Text, 60)}\" is not NAME=value.";
                    return null;
                }

                environment[match.Groups[1].Value] = match.Groups[2].Value;
            }
        }

        var directory = Text(state, DirectoryField);

        return new ServerDescriptor(
            Id: id,
            DisplayName: TextSanitizer.Clean(name, TextSanitizer.NameLength),
            Command: command,
            Arguments: ServerDescriptor.SplitArguments(Text(state, ArgumentsField)),
            WorkingDirectory: directory.Length == 0 ? null : directory)
        {
            Environment = environment,
            Url = address.Length > 0 ? address : null,
            Enabled = state.Find(EnabledField) is BooleanFieldState { Value: true },
        };
    }

    /// <summary>The key a new server is filed under: its name, made unique.</summary>
    public static string NewId(ServerConfiguration configuration, string displayName)
    {
        ArgumentNullException.ThrowIfNull(configuration);
        return configuration.UniqueId(string.IsNullOrWhiteSpace(displayName) ? "server" : displayName.Trim());
    }

    private static string Text(FormState state, string path)
        => (state.Find(path) as TextFieldState)?.Text.Trim() ?? "";

    private static void SetText(FormState state, string path, string? value)
    {
        if (state.Find(path) is TextFieldState field) field.Text = value ?? "";
    }

    private static JsonElement Parse(string json) => JsonDocument.Parse(json).RootElement.Clone();
}
